import{_ as a,o as e,c as d,a2 as s}from"./chunks/framework.BW2T23B9.js";const n="/docs/images/authoring/workshop-canvas.svg",o="/docs/images/authoring/textbook-pipeline.svg",g=JSON.parse('{"title":"教材导入","description":"","frontmatter":{},"headers":[],"relativePath":"authoring/textbook-import.md","filePath":"authoring/textbook-import.md","lastUpdated":null}'),r={name:"authoring/textbook-import.md"};function i(l,t,p,h,c,b){return e(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="教材导入" tabindex="-1">教材导入 <a class="header-anchor" href="#教材导入" aria-label="Permalink to &quot;教材导入&quot;">​</a></h1><blockquote><p>教材导入是半自动课程生产流程。模型负责抽取与生成草稿；<strong>作者负责审校、冲突处理、验证与发布</strong>。GUI 工坊是这一流程的唯一入口。</p></blockquote><p><img src="'+n+'" alt="课程工坊三栏画布：左 教材/知识/气泡 · 中 AI 轨道 · 右 结构大纲 + 导入"></p><p><img src="'+o+`" alt="教材导入流水线：状态灯 / 审校 / 气泡 / 轨道 / 导入策略"></p><h2 id="支持输入" tabindex="-1">支持输入 <a class="header-anchor" href="#支持输入" aria-label="Permalink to &quot;支持输入&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>支持范围</th><th>备注</th></tr></thead><tbody><tr><td>Markdown / 纯文本</td><td>UTF-8</td><td>按标题切章</td></tr><tr><td>PDF</td><td>文本原生 PDF</td><td>扫描件需在外部 OCR 后再导入</td></tr><tr><td>Word</td><td><code>.doc</code> / <code>.docx</code></td><td>依赖 <code>python-docx</code></td></tr><tr><td>图片</td><td>作为 vision 附件</td><td>取决于所配置模型的视觉能力</td></tr></tbody></table><p>源文件<strong>不</strong>复制进项目目录。项目文件仅保存路径引用与抽取结果，便于作者保留单一真理源。</p><h2 id="ocr-与扫描件" tabindex="-1">OCR 与扫描件 <a class="header-anchor" href="#ocr-与扫描件" aria-label="Permalink to &quot;OCR 与扫描件&quot;">​</a></h2><p>OCR 是<strong>可选外部依赖</strong>。GUI 不内置。处理流程：</p><ol><li>安装 <a href="https://github.com/tesseract-ocr/tesseract" target="_blank" rel="noreferrer">Tesseract</a> 与目标语言包。</li><li>扫描件 PDF：<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ocrmypdf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> input.pdf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> output.pdf</span></span></code></pre></div></li><li>图片：使用 <code>pytesseract</code> 或在外部工具中转写。</li><li>将识别后的文本版 PDF / Markdown 重新导入工坊。</li></ol><p>未做 OCR 的扫描件 PDF 会触发「未提取到文本」状态灯。</p><h2 id="工作区与双轨项目" tabindex="-1">工作区与双轨项目 <a class="header-anchor" href="#工作区与双轨项目" aria-label="Permalink to &quot;工作区与双轨项目&quot;">​</a></h2><p>GUI 工坊（<code>tool/gui</code> 的非模态窗口）由「项目库」与「创意画布」组成。所有中间产物落在 <code>tool/gui/var/textbooks/{project_id}/project.json</code>，允许中断后恢复。</p><table tabindex="0"><thead><tr><th>项目模式</th><th>建立方式</th><th>适用</th></tr></thead><tbody><tr><td><strong>教材项目</strong></td><td>项目库 → 从教材新建 → 选文件 + 语言对</td><td>自上而下抽取；Grounded 编排</td></tr><tr><td><strong>空白 AI 项目</strong></td><td>项目库 → 空白 AI 项目 → 填名称 + 语言对</td><td>无教材自由生成；左栏教材/知识标记为「(可选)」</td></tr></tbody></table><h3 id="画布三栏" tabindex="-1">画布三栏 <a class="header-anchor" href="#画布三栏" aria-label="Permalink to &quot;画布三栏&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─ 左栏 ──────────────┐  ┌─ 中栏 AI 轨道 ──────┐  ┌─ 右栏 ───────────────────────┐</span></span>
<span class="line"><span>│ 教材与章节           │  │ 主题 / CEFR / 模板   │  │ 结构大纲（默认）· 对话 · 导入 │</span></span>
<span class="line"><span>│ 知识点审校           │  │ 聚焦条 / Ctrl+Enter  │  │ 试做 · diff · AI 修复         │</span></span>
<span class="line"><span>│ 气泡池（≤ 200）      │  │ [ AI 核心 开始设计 ] │  │                              │</span></span>
<span class="line"><span>└──────────────────────┘  └──────────────────────┘  └──────────────────────────────┘</span></span></code></pre></div><p>顶栏 checklist：<code>○/✓ 素材 · 知识 · 草稿 · 导入</code>（可点击跳转）。</p><h2 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 选文件</span></span>
<span class="line"><span>2. 提取文本</span></span>
<span class="line"><span>3. 按章节切分</span></span>
<span class="line"><span>4. 选预设 + 并发数</span></span>
<span class="line"><span>5. 抽取词汇 / 表达 / 语法点 / 对话</span></span>
<span class="line"><span>6. 处理红（error）/ 黄（warning）标记</span></span>
<span class="line"><span>7. 勾选入池</span></span>
<span class="line"><span>8. 生成 Section / Lesson 草稿</span></span>
<span class="line"><span>9. 查结构 + 覆盖率 + JSON diff</span></span>
<span class="line"><span>10. 选冲突策略</span></span>
<span class="line"><span>11. 导入内存课程项目</span></span>
<span class="line"><span>12. 在主窗口保存 → 运行 validate + lint</span></span></code></pre></div><p>抽取过程支持中断与续作；勾选、知识点、聊天、草稿、tab/splitter 布局均自动保存。</p><h2 id="章节抽取" tabindex="-1">章节抽取 <a class="header-anchor" href="#章节抽取" aria-label="Permalink to &quot;章节抽取&quot;">​</a></h2><h3 id="滑窗" tabindex="-1">滑窗 <a class="header-anchor" href="#滑窗" aria-label="Permalink to &quot;滑窗&quot;">​</a></h3><p>超出预设字数的章按段落边界切成带重叠的滑窗，逐窗抽取后按键（词 + 翻译 / 语法标题）去重合并。<code>id</code> 仍按 <code>ch-{slug}-</code> 确定性生成。预设参数：</p><table tabindex="0"><thead><tr><th>参数</th><th>默认</th><th>含义</th></tr></thead><tbody><tr><td><code>window_chars</code></td><td>12000</td><td>单次抽取字符上限；<code>0</code> 关闭</td></tr><tr><td><code>overlap_chars</code></td><td>800</td><td>滑窗重叠字符数</td></tr></tbody></table><h3 id="状态灯" tabindex="-1">状态灯 <a class="header-anchor" href="#状态灯" aria-label="Permalink to &quot;状态灯&quot;">​</a></h3><table tabindex="0"><thead><tr><th>灯</th><th>含义</th><th>可执行动作</th></tr></thead><tbody><tr><td>绿</td><td>抽取通过</td><td>入池 / 重新抽取</td></tr><tr><td>黄</td><td>有 warning（空翻译、覆盖率偏低、语言混入）</td><td>修复 / 重抽</td></tr><tr><td>红</td><td>抽取失败</td><td>重试 / 仅抽词汇 / 跳过</td></tr><tr><td>灰</td><td>未抽取</td><td>触发抽取</td></tr></tbody></table><h3 id="失败级联" tabindex="-1">失败级联 <a class="header-anchor" href="#失败级联" aria-label="Permalink to &quot;失败级联&quot;">​</a></h3><p><code>standard</code> 抽取失败时自动降级为「仅词汇（vocab_only）」重试一次（日志写明「自动降级」）。再失败才标红。开关：<code>QSettings/textbook/auto_cascade</code>，默认开。</p><h3 id="按质量重抽" tabindex="-1">按质量重抽 <a class="header-anchor" href="#按质量重抽" aria-label="Permalink to &quot;按质量重抽&quot;">​</a></h3><p>对红 / 黄章提供「按质量重抽」，把具体问题（空翻译、覆盖率偏低、语言混入等）回灌给 AI，输出完整修正版替换本章并重算质量分。</p><h2 id="预设" tabindex="-1">预设 <a class="header-anchor" href="#预设" aria-label="Permalink to &quot;预设&quot;">​</a></h2><table tabindex="0"><thead><tr><th>预设</th><th>目标</th><th>默认倾向</th></tr></thead><tbody><tr><td><code>general</code></td><td>通用教材</td><td>均衡抽取</td></tr><tr><td><code>grammar</code></td><td>语法书</td><td>低温度、强调规则</td></tr><tr><td><code>dialogue</code></td><td>对话书</td><td>强调表达与口语</td></tr><tr><td><code>reading</code></td><td>阅读材料</td><td>词汇抽取为主</td></tr></tbody></table><p>预设仅影响抽取参数与 prompt 块，<strong>不免除审校</strong>。</p><h2 id="气泡池与-grounded-生成" tabindex="-1">气泡池与 Grounded 生成 <a class="header-anchor" href="#气泡池与-grounded-生成" aria-label="Permalink to &quot;气泡池与 Grounded 生成&quot;">​</a></h2><p>入池上限约 200。点击「将选中词加入轨道」或拖入中栏后进入气泡池。生成时 AI 优先从池中选词；池外新词带 <code>new</code> 标签，便于审校时定位。</p><h2 id="ai-轨道" tabindex="-1">AI 轨道 <a class="header-anchor" href="#ai-轨道" aria-label="Permalink to &quot;AI 轨道&quot;">​</a></h2><table tabindex="0"><thead><tr><th>控件</th><th>含义</th></tr></thead><tbody><tr><td>主题</td><td>Section 教学主题</td></tr><tr><td>CEFR</td><td>目标等级</td></tr><tr><td>单元数</td><td>Section 内 Unit 数（≤ 60）</td></tr><tr><td>课时/单元</td><td>每 Unit 的 Lesson 数（≤ 40）</td></tr><tr><td>模板</td><td>课时 <code>template</code> 选型</td></tr><tr><td>AI 悄悄话</td><td>编排意图（自然语言）</td></tr></tbody></table><p>聚焦条显示「将使用资源池：N 词 · M 表达 · K 语法」。点「AI 核心」或 <code>Ctrl+Enter</code> 触发生成。</p><h2 id="生成模式" tabindex="-1">生成模式 <a class="header-anchor" href="#生成模式" aria-label="Permalink to &quot;生成模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>流程</th><th>适用</th></tr></thead><tbody><tr><td>快速（整节）</td><td>一次出 Section 草稿</td><td>草稿探索</td></tr><tr><td>精修（流水线）</td><td>Plan → 大纲 → 分课 → 校验 → 质量分 → 修复 → 解释 → ReadyImport</td><td>发布候选</td></tr></tbody></table><p>精修流水线由 <code>backend/ai_pipeline.py</code> 状态机驱动；右栏 checklist 实时显示每步状态。<strong>流水线只到草稿为止</strong>。导入仍走原有「校验 → 目标选择 → diff/merge 预览 → 人工确认」流程，<strong>不</strong>自动导入。</p><p>修复阶段规则：先规则修复，LLM 仅处理剩余 error，<strong>不得</strong>删除既有 id，否则回滚。</p><h2 id="对话与高级" tabindex="-1">对话与高级 <a class="header-anchor" href="#对话与高级" aria-label="Permalink to &quot;对话与高级&quot;">​</a></h2><p>右栏「对话与高级」支持：</p><ul><li>聊天（含多模态附件）</li><li>Prompt 模板库与历史</li><li><code>[genre]</code> 多模板（语法书 / 对话书 / 阅读）</li><li>JSON 输出（默认折叠）</li><li>AI 分析失败原因</li></ul><p>主参数（主题 / CEFR / 模板）始终在中栏轨道，不在聊天中重复。</p><h2 id="章节导入" tabindex="-1">章节导入 <a class="header-anchor" href="#章节导入" aria-label="Permalink to &quot;章节导入&quot;">​</a></h2><table tabindex="0"><thead><tr><th>策略</th><th>行为</th><th>风险</th></tr></thead><tbody><tr><td>合并预览（默认）</td><td>逐项决定</td><td>低</td></tr><tr><td>跳过已存在</td><td>保留现有 Section</td><td>低</td></tr><tr><td>覆盖已存在</td><td>整体替换</td><td>高</td></tr><tr><td>作为新 Section</td><td>生成新 ID 并存</td><td>中</td></tr></tbody></table><p>幂等：重复导入不制造废节点。</p><h2 id="冲突处理" tabindex="-1">冲突处理 <a class="header-anchor" href="#冲突处理" aria-label="Permalink to &quot;冲突处理&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>项目内规范化 key 碰撞</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>   是否与现有课程 ID 冲突？</span></span>
<span class="line"><span>        ├─ 是 → 三选一：保留 / 覆盖 / 追加新 id</span></span>
<span class="line"><span>        └─ 否 → 合并为既有 ID</span></span></code></pre></div><p>去重依据规范化 key，<strong>不</strong>依据字符串相似度。<code>new</code> 标签词条强制人工确认。</p><h2 id="失败处理" tabindex="-1">失败处理 <a class="header-anchor" href="#失败处理" aria-label="Permalink to &quot;失败处理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处置</th></tr></thead><tbody><tr><td>未切章</td><td>检查 Markdown 标题层级</td></tr><tr><td>PDF 无文本</td><td>走 OCR 流程</td></tr><tr><td>单章抽取失败</td><td>重试 / 仅抽词汇 / 跳过</td></tr><tr><td>JSON 不通过</td><td>回到草稿修复，不直接覆盖</td></tr><tr><td>价格未知</td><td>只显示 Token，不生成误导性成本</td></tr></tbody></table><h2 id="语言对抽取模板" tabindex="-1">语言对抽取模板 <a class="header-anchor" href="#语言对抽取模板" aria-label="Permalink to &quot;语言对抽取模板&quot;">​</a></h2><p><code>Turkish ↔ Chinese</code> 内置抽取规则块（强调元音和谐、敬语形式、term 禁止中文字符、翻译用简体中文）。其他语言对可在「设置 → 提取 Prompt」tab 持久化覆盖。优先级：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>内存 register &gt; 持久化覆盖 &gt; 内置语言对包 &gt; 内置默认</span></span></code></pre></div><p>实现见 <code>tool/gui/src/backend/knowledge_prompt.py</code> 与 <code>tool/gui/src/backend/ai_prompt_library.py</code>。</p><h2 id="性能与节流" tabindex="-1">性能与节流 <a class="header-anchor" href="#性能与节流" aria-label="Permalink to &quot;性能与节流&quot;">​</a></h2><ul><li>气泡池增量刷新 + debounce。</li><li>草稿自动保存节流。</li><li>校验始终只走 <code>CourseAdapter</code> / <code>course_cli</code>，不绕开。</li></ul><h2 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>动作</th></tr></thead><tbody><tr><td><code>Ctrl+Enter</code></td><td>从轨道生成</td></tr><tr><td><code>Esc</code></td><td>任务进行中：确认后取消</td></tr><tr><td>头栏 checklist 单元</td><td>跳转到对应栏</td></tr></tbody></table><h2 id="与-gui-主窗口的衔接" tabindex="-1">与 GUI 主窗口的衔接 <a class="header-anchor" href="#与-gui-主窗口的衔接" aria-label="Permalink to &quot;与 GUI 主窗口的衔接&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工坊草稿 ──import──► 主窗口课程树（新增/合并/覆盖/追加）</span></span>
<span class="line"><span>                       │</span></span>
<span class="line"><span>                       ▼</span></span>
<span class="line"><span>                  主窗口保存 (Ctrl+S)</span></span>
<span class="line"><span>                       │</span></span>
<span class="line"><span>                       ▼</span></span>
<span class="line"><span>            CourseAdapter.save() → validate + lint</span></span>
<span class="line"><span>                       │</span></span>
<span class="line"><span>                       ▼</span></span>
<span class="line"><span>                  磁盘 JSON 写盘</span></span></code></pre></div><p>导入成功后 GUI 可询问是否「切换教师模式并定位该章节（及首课）」。导入后<strong>必须</strong>在主窗口保存。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/editor">课程编辑器</a></li><li><a href="/docs/authoring/course-layout">课程目录约定</a></li><li><a href="/docs/authoring/resource-files">资源文件</a></li><li><a href="/docs/authoring/lesson-schema">Lesson JSON 结构</a></li><li><a href="/docs/authoring/validation">校验与 Lint</a></li><li><a href="/docs/authoring/release-checklist">发布检查表</a></li></ul>`,67)])])}const k=a(r,[["render",i]]);export{g as __pageData,k as default};
